/* NFL Injury Report — verified reporter & source directory front end.
 *
 * Renders data/latest/directory.json (regenerated by scheduled GitHub Actions).
 * The page is fully static and honest about status: only an explicit
 * machine-verified status gets a green badge; everything else is a visible
 * manual-review/search link rather than a guessed profile.
 */
(function () {
  "use strict";

  var state = {
    data: null,
    tab: "clubs",
    clubQuery: "",
    natQuery: "",
    natFilter: "",
    beatQuery: "",
    beatTeam: ""
  };

  var NETWORK_META = {
    x: { label: "X", title: "X (Twitter)" },
    facebook: { label: "f", title: "Facebook" },
    instagram: { label: "IG", title: "Instagram" },
    snapchat: { label: "Snap", title: "Snapchat" },
    tiktok: { label: "TikTok", title: "TikTok" },
    youtube: { label: "YT", title: "YouTube" },
    bluesky: { label: "BSky", title: "Bluesky" }
  };

  function $(sel, root) { return (root || document).querySelector(sel); }
  function $$(sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text !== undefined && text !== null) n.textContent = String(text);
    return n;
  }

  function link(href, label, cls, title) {
    var a = el("a", cls || "soc", label);
    a.href = href;
    a.target = "_blank";
    a.rel = "noopener";
    if (title) a.title = title;
    return a;
  }

  function relative(iso) {
    if (!iso) return "";
    var t = Date.parse(iso);
    if (isNaN(t)) return "";
    var diff = Math.round((Date.now() - t) / 1000);
    var future = diff < 0;
    diff = Math.abs(diff);
    var out;
    if (diff < 45) out = diff + "s";
    else if (diff < 3600) out = Math.round(diff / 60) + "m";
    else if (diff < 86400) out = Math.round(diff / 3600) + "h";
    else out = Math.round(diff / 86400) + "d";
    return future ? "in " + out : out + " ago";
  }

  function stamp(iso) {
    if (!iso) return "";
    var d = new Date(iso);
    if (isNaN(d.getTime())) return iso;
    return d.toLocaleString(undefined, {
      month: "short", day: "numeric", hour: "2-digit", minute: "2-digit"
    });
  }

  function counter(label, value) {
    var c = el("div", "counter");
    c.appendChild(el("b", "", value));
    c.appendChild(el("span", "", label));
    return c;
  }

  /* ----------------------------------------------------------- badges ---- */

  var BSKY_BADGE = {
    verified: ["verified", "Bluesky verified"],
    candidate: ["candidate", "name match · no checkmark · review"],
    "not-found": ["absent", "no genuine account found"],
    "not-probed": ["pending", "auto-check pending"],
    "probe-error": ["pending", "probe failed · will retry"]
  };
  var X_BADGE = {
    verified: ["verified", "X profile verified automatically"],
    manual: ["manual", "click to verify on X (no free API)"],
    "search-only": ["manual", "exact-name search — confirm the account yourself"]
  };

  function vbadge(kind, text, title) {
    var b = el("span", "vbadge " + kind, text);
    if (title) b.title = title;
    return b;
  }

  function socPill(network, url, label, title) {
    if (!url) return null;
    var meta = NETWORK_META[network] || { label: network, title: network };
    var a = link(url, label || meta.label, "soc soc-" + network, title || meta.title);
    return a;
  }

  /* ------------------------------------------------------------- load ---- */

  function loadData() {
    var bases = ["", "../"];
    var attempt = 0;
    function next() {
      var url = bases[attempt] + "data/latest/directory.json";
      fetch(url, { cache: "no-store" })
        .then(function (r) {
          if (!r.ok) throw new Error("HTTP " + r.status);
          return r.json();
        })
        .then(function (d) { state.data = d; state.base = bases[attempt]; render(); })
        .catch(function () {
          attempt += 1;
          if (attempt < bases.length) { next(); return; }
          $("#statusText").textContent = "snapshot missing";
          $("#globalNotice").className = "notice warn";
          $("#globalNotice").textContent =
            "data/latest/directory.json is not present yet. A GitHub Actions collection run " +
            "creates it (or run: python3 -m collectors.directory build).";
        });
    }
    next();
  }

  /* ------------------------------------------------------------ clubs ---- */

  function leagueStrip(data) {
    var wrap = el("div", "league-strip");
    data.league.forEach(function (r) {
      var card = el("div", "dir-card league-card");
      var head = el("div", "dc-head");
      head.appendChild(vbadge("verified", "Official"));
      head.appendChild(el("h3", "", r.name));
      card.appendChild(head);
      card.appendChild(el("p", "dc-role", r.role));
      var links = el("div", "dc-links");
      links.appendChild(link(r.url, "Open official page ↗", "soc"));
      links.appendChild(link(r.evidence_url, "evidence URL", "soc ghost-soc"));
      card.appendChild(links);
      wrap.appendChild(card);
    });
    return wrap;
  }

  function clubCard(team) {
    var card = el("div", "dir-card club-card");
    var head = el("div", "dc-head");
    head.appendChild(el("span", "team-code", team.code));
    head.appendChild(el("h3", "", team.name));
    var ok = team.probe && team.probe.status === 200 && team.official_site;
    if (!ok) {
      head.appendChild(vbadge("pending", "probe pending"));
    }
    card.appendChild(head);

    var links = el("div", "dc-links");
    if (team.official_site) {
      links.appendChild(link(team.official_site, "🌐 Official club site", "soc"));
    }
    links.appendChild(link(team.nfl_team_url, "nfl.com team page (source)", "soc ghost-soc"));
    card.appendChild(links);

    var socials = el("div", "dc-socials");
    var order = ["x", "facebook", "instagram", "snapchat", "tiktok", "youtube"];
    var found = false;
    order.forEach(function (net) {
      var s = (team.socials || {})[net];
      if (!s) return;
      found = true;
      socials.appendChild(socPill(net, s.url, null,
        (NETWORK_META[net] ? NETWORK_META[net].title : net) + " " + s.handle +
        " — as published on the club's nfl.com page"));
    });
    if (!found) {
      socials.appendChild(el("span", "muted small", "No social links parsed from the nfl.com page yet."));
    }
    card.appendChild(socials);

    var foot = el("div", "dc-foot muted");
    if (team.probe && team.probe.status === 200) {
      var txt = "Parsed from nfl.com" + (team.probe.fetched_at ? " · " + relative(team.probe.fetched_at) : "");
      foot.textContent = txt;
      if (team.probe.note) foot.title = team.probe.note;
    } else if (team.probe && team.probe.error) {
      foot.textContent = "Probe failed (" + team.probe.error + "); no handles guessed.";
      foot.className = "dc-foot warn-text";
    } else {
      foot.textContent = "Not probed yet (offline bootstrap); next live run fills this row.";
    }
    card.appendChild(foot);
    return card;
  }

  function renderClubs(data) {
    var host = $("#clubGrid");
    host.innerHTML = "";
    var q = state.clubQuery.trim().toLowerCase();
    data.teams.forEach(function (team) {
      if (q && (team.name.toLowerCase().indexOf(q) < 0 &&
                team.code.toLowerCase().indexOf(q) < 0 &&
                (team.slug || "").toLowerCase().indexOf(q) < 0)) return;
      host.appendChild(clubCard(team));
    });

    var counters = $("#clubCounters");
    counters.innerHTML = "";
    var parsed = data.teams.filter(function (t) { return t.probe && t.probe.status === 200; }).length;
    var withX = data.teams.filter(function (t) { return (t.socials || {}).x; }).length;
    counters.appendChild(counter("clubs parsed", parsed + " / " + data.teams.length));
    counters.appendChild(counter("official X links", withX));
    counters.appendChild(counter("league pages", data.league.length));

    var panel = $("#panel-clubs");
    var existing = panel.querySelector(".league-strip");
    if (existing) existing.remove();
    panel.querySelector(".controls").insertAdjacentElement("afterend", leagueStrip(data));
  }

  /* --------------------------------------------------------- nationals --- */

  function evidenceLinks(row) {
    var wrap = el("div", "dc-links");
    (row.evidence || []).forEach(function (u, i) {
      wrap.appendChild(link(u, "ESPN attribution " + (i + 1) + " ↗", "soc ghost-soc"));
    });
    return wrap;
  }

  function bskyLine(row) {
    var line = el("div", "acc-line");
    var b = row.bluesky || { status: "not-probed" };
    var badge = BSKY_BADGE[b.status] || ["pending", b.status];
    line.appendChild(vbadge(badge[0], "BSky", badge[1]));

    if (b.status === "verified" || b.status === "candidate") {
      line.appendChild(link(b.url, b.handle, "soc"));
      if (b.bio_snippet) {
        var bio = el("span", "acc-note muted", "“" + b.bio_snippet + "”");
        line.appendChild(bio);
      }
    } else if (b.status === "not-found") {
      line.appendChild(el("span", "acc-note muted", b.detail || "no genuine Bluesky account found"));
      if (b.rejected && b.rejected.length) {
        var det = el("details", "rejected-details");
        var sum = el("summary", "", "show " + b.rejected.length + " impostor/mirror search results");
        det.appendChild(sum);
        var ul = el("ul", "rejected-list");
        b.rejected.forEach(function (r) {
          var li = el("li");
          if (r.handle && r.handle !== "handle.invalid") {
            li.appendChild(link("https://bsky.app/profile/" + encodeURIComponent(r.handle),
              r.handle, "soc fraud-link"));
          } else {
            li.appendChild(el("span", "", r.handle || "(no handle)"));
          }
          li.appendChild(el("span", "muted small", " — " + (r.display_name || "") + " · " + r.reason));
          ul.appendChild(li);
        });
        det.appendChild(ul);
        line.appendChild(det);
      }
    } else {
      line.appendChild(el("span", "acc-note muted",
        b.status === "probe-error" ? ("probe error: " + (b.detail || "")) :
        "automated check has not run yet; the candidate below is not asserted as theirs"));
      if (b.url) line.appendChild(link(b.url, "possible handle (unverified) ↗", "soc ghost-soc"));
    }
    return line;
  }

  function xLine(row) {
    var line = el("div", "acc-line");
    var x = row.x || { status: "manual" };
    var badge = X_BADGE[x.status] || ["manual", x.detail || "manual review"];
    line.appendChild(vbadge(badge[0], "X", badge[1]));
    if (x.url) line.appendChild(link(x.url, "@" + (x.handle || ""), "soc"));
    line.appendChild(el("span", "acc-note muted",
      x.status === "verified" ? (x.detail || "") :
      "no free X verification API in 2026 — click through and confirm yourself"));
    return line;
  }

  function nationalCard(row) {
    var card = el("div", "dir-card nat-card");
    var head = el("div", "dc-head");
    if (row.bluesky && row.bluesky.status === "verified") {
      head.appendChild(vbadge("verified", "verified"));
    } else if (row.observed_in_feed) {
      head.appendChild(vbadge("manual", "seen in feed"));
    } else {
      head.appendChild(vbadge("pending", "seed"));
    }
    head.appendChild(el("h3", "", row.name));
    card.appendChild(head);
    card.appendChild(el("p", "dc-role", row.role || ""));

    if (row.observed_in_feed) {
      var teams = (row.feed_teams || []).join(", ");
      card.appendChild(el("p", "dc-feed",
        "Named by ESPN on " + row.feed_updates + " injury attribution(s)" +
        (teams ? " across " + teams : "") +
        (row.latest_feed_at ? " · latest " + relative(row.latest_feed_at) : "")));
    }

    card.appendChild(bskyLine(row));
    card.appendChild(xLine(row));

    var ev = evidenceLinks(row);
    if (ev.children.length) card.appendChild(ev);

    if (row.notes) card.appendChild(el("p", "dc-notes muted", row.notes));
    if (row.outlet_evidence) {
      card.appendChild(el("p", "dc-notes muted", "Outlet evidence: " + row.outlet_evidence));
    }
    return card;
  }

  function renderNational(data) {
    var host = $("#nationalList");
    host.innerHTML = "";
    var q = state.natQuery.trim().toLowerCase();
    var f = state.natFilter;
    data.national.forEach(function (row) {
      if (q) {
        var hay = [row.name, row.role, row.bluesky && row.bluesky.handle, row.x && row.x.handle,
                   (row.feed_teams || []).join(" ")].join(" ").toLowerCase();
        if (hay.indexOf(q) < 0) return;
      }
      if (f === "verified" && !(row.bluesky && row.bluesky.status === "verified")) return;
      if (f === "feed" && !row.observed_in_feed) return;
      if (f === "unverified" && row.bluesky && row.bluesky.status === "verified") return;
      host.appendChild(nationalCard(row));
    });
    if (!host.children.length) host.appendChild(el("div", "empty", "No reporters match."));

    var counters = $("#nationalCounters");
    counters.innerHTML = "";
    counters.appendChild(counter("insiders", data.national.length));
    counters.appendChild(counter("Bluesky verified", data.counts.bluesky_verified));
    counters.appendChild(counter("name-match candidates", data.counts.bluesky_candidates));
    counters.appendChild(counter("seen in feed",
      data.national.filter(function (r) { return r.observed_in_feed; }).length));
  }

  /* -------------------------------------------------------------- beat --- */

  function beatCard(writer) {
    var card = el("div", "dir-card beat-card");
    var head = el("div", "dc-head");
    head.appendChild(el("h3", "", writer.name));
    if (writer.teams.length > 1) head.appendChild(vbadge("manual", writer.teams.length + " clubs · review"));
    card.appendChild(head);
    card.appendChild(el("p", "dc-role",
      (writer.outlet || "outlet as printed by ESPN") + " · " + writer.updates +
      " attributed update(s)" + (writer.latest_at ? " · latest " + relative(writer.latest_at) : "")));

    var chips = el("div", "chips static-chips");
    writer.teams.forEach(function (t, i) {
      chips.appendChild(el("span", "chip" + (i ? "" : " primary-team"), t));
    });
    card.appendChild(chips);

    var links = el("div", "dc-links");
    links.appendChild(link(writer.x_search_url, "🔎 Search X by exact name", "soc"));
    links.appendChild(link(writer.google_news_url, "📰 Google News search", "soc"));
    (writer.evidence || []).forEach(function (u, i) {
      links.appendChild(link(u, "ESPN attribution " + (i + 1), "soc ghost-soc"));
    });
    card.appendChild(links);
    card.appendChild(el("p", "dc-notes muted",
      "No social handle is asserted for this writer: the search links open an exact-name query " +
      "so the genuine account can be confirmed manually."));
    return card;
  }

  function renderBeat(data) {
    var chipHost = $("#beatTeamChips");
    var groupHost = $("#beatGroups");
    chipHost.innerHTML = "";
    groupHost.innerHTML = "";

    var teamsWith = {};
    data.beat.forEach(function (w) {
      w.teams.forEach(function (t) { teamsWith[t] = (teamsWith[t] || 0) + 1; });
    });
    var ordered = data.teams.map(function (t) { return t.code; })
      .filter(function (c) { return teamsWith[c]; });

    var allChip = el("button", "chip" + (state.beatTeam ? "" : " active"), "All");
    allChip.setAttribute("data-team", "");
    chipHost.appendChild(allChip);
    ordered.forEach(function (code) {
      var c = el("button", "chip" + (state.beatTeam === code ? " active" : ""),
        code + " (" + teamsWith[code] + ")");
      c.setAttribute("data-team", code);
      chipHost.appendChild(c);
    });

    var q = state.beatQuery.trim().toLowerCase();
    var groups = state.beatTeam ? [state.beatTeam] : ordered;
    groups.forEach(function (code) {
      var writers = data.beat.filter(function (w) {
        return w.teams.indexOf(code) >= 0;
      }).filter(function (w) {
        if (!q) return true;
        return [w.name, w.outlet, w.teams.join(" ")].join(" ").toLowerCase().indexOf(q) >= 0;
      });
      if (!writers.length) return;
      var block = el("div", "team-block");
      var th = el("div", "team-head");
      th.appendChild(el("span", "team-code", code));
      th.appendChild(el("h3", "", (data.teams.filter(function (t) { return t.code === code; })[0] || {}).name || code));
      th.appendChild(el("span", "team-meta", writers.length + " writer(s) named by ESPN"));
      block.appendChild(th);
      var body = el("div", "team-body beat-body");
      writers.forEach(function (w) { body.appendChild(beatCard(w)); });
      block.appendChild(body);
      groupHost.appendChild(block);
    });
    if (!groupHost.children.length) {
      groupHost.appendChild(el("div", "empty", "No beat writers in the current snapshot match."));
    }

    var counters = $("#beatCounters");
    counters.innerHTML = "";
    counters.appendChild(counter("writers", data.beat.length));
    counters.appendChild(counter("clubs covered", ordered.length));
    counters.appendChild(counter("cross-club flags",
      data.beat.filter(function (w) { return w.teams.length > 1; }).length));
  }

  /* ---------------------------------------------------------- warnings --- */

  function renderWarnings(data) {
    var host = $("#warningList");
    host.innerHTML = "";

    var seen = {};
    var n = 0;
    data.national.forEach(function (row) {
      (row.bluesky && row.bluesky.rejected || []).forEach(function (r) {
        var key = row.name + "|" + r.handle + "|" + r.display_name;
        if (seen[key]) return;
        seen[key] = true;
        var card = el("div", "flag-card sev-medium");
        var h = el("h4");
        h.appendChild(vbadge("fraud", "non-official"));
        h.appendChild(el("span", "", (r.handle || "(no handle)") + " — not " + row.name));
        card.appendChild(h);
        card.appendChild(el("p", "",
          "Appears when searching Bluesky for “" + row.name + "”. Display name: " +
          (r.display_name || "(empty)") + ". " + r.reason + "."));
        var links = el("div", "dc-links");
        if (r.handle && r.handle !== "handle.invalid") {
          links.appendChild(link("https://bsky.app/profile/" + encodeURIComponent(r.handle),
            "inspect the account yourself ↗", "soc ghost-soc"));
        }
        card.appendChild(links);
        host.appendChild(card);
        n += 1;
      });
    });

    (data.irregularities || []).forEach(function (f) {
      if (f.code === "DIRECTORY_LOOKALIKE_ACCOUNT") return; // already rendered above
      var card = el("div", "flag-card sev-" + (f.severity || "low"));
      var h = el("h4");
      h.appendChild(vbadge(f.severity === "medium" ? "manual" : "pending", f.code.replace("DIRECTORY_", "")));
      h.appendChild(el("span", "", f.title));
      card.appendChild(h);
      card.appendChild(el("p", "", f.detail));
      var links = el("div", "dc-links");
      (f.evidence || []).forEach(function (e) {
        if (e.url) links.appendChild(link(e.url, (e.label || "evidence") + " ↗", "soc ghost-soc"));
      });
      if (links.children.length) card.appendChild(links);
      host.appendChild(card);
      n += 1;
    });

    if (!n) host.appendChild(el("div", "empty", "No impostor accounts or directory irregularities recorded."));
    $("#warnCount").textContent = n || "";
  }

  /* ------------------------------------------------------------ method --- */

  function renderMethod(data) {
    var host = $("#methodBody");
    host.innerHTML = "";
    var m = data.methodology || {};
    Object.keys(m).forEach(function (key) {
      var card = el("div", "dir-card method-card");
      var title = key.replace(/_/g, " ").replace(/^./, function (c) { return c.toUpperCase(); });
      card.appendChild(el("h3", "method-h", title));
      card.appendChild(el("p", "muted", m[key]));
      host.appendChild(card);
    });
    var legend = el("div", "dir-card method-card");
    legend.appendChild(el("h3", "method-h", "Badge legend"));
    [
      ["verified", "Machine-verified through a free public endpoint with an exact identity match."],
      ["candidate", "Identity looks right but the platform's own checkmark is absent — click to confirm."],
      ["manual", "No free automated verification exists; the link opens the real page for a one-click human check."],
      ["absent", "No genuine account found; search results were mirrors/bots/impostors (see Fraud warnings)."],
      ["pending", "Automated check has not run yet or failed transiently; never treated as verified."],
      ["fraud", "Known non-official / impersonation-labeled account. Never used as a source."]
    ].forEach(function (pair) {
      var line = el("div", "legend-line");
      line.appendChild(vbadge(pair[0], pair[0]));
      line.appendChild(el("span", "muted", pair[1]));
      legend.appendChild(line);
    });
    host.appendChild(legend);

    if (data.provenance && (data.provenance.teams || data.provenance.social)) {
      var prov = el("div", "dir-card method-card");
      prov.appendChild(el("h3", "method-h", "Snapshot provenance"));
      if (data.provenance.teams) prov.appendChild(el("p", "muted small", "Clubs: " + data.provenance.teams));
      if (data.provenance.social) prov.appendChild(el("p", "muted small", "Social verification: " + data.provenance.social));
      host.appendChild(prov);
    }
  }

  /* ------------------------------------------------------------- shell --- */

  function renderStatus(data) {
    var t = data.generated_at ? Date.parse(data.generated_at) : NaN;
    $("#statusText").textContent =
      "directory " + (data.mode || "") + " snapshot · " +
      (isNaN(t) ? "unknown age" : relative(data.generated_at));
    var dot = $("#statusDot");
    dot.className = "dot";
    if (!isNaN(t)) {
      var ageH = (Date.now() - t) / 3600000;
      if (ageH < 26) dot.classList.add("fresh");
      else if (ageH < 72) dot.classList.add("stale");
      else dot.classList.add("dead");
    }
    $("#footStamp").textContent =
      "Directory generated " + (data.generated_at || "?") +
      (data.mode === "offline" ? " (offline build using cached/observed evidence; live CI runs refresh it)" : "");
  }

  function render() {
    var data = state.data;
    renderStatus(data);
    renderClubs(data);
    renderNational(data);
    renderBeat(data);
    renderWarnings(data);
    renderMethod(data);
  }

  /* ------------------------------------------------------------ events --- */

  $$(".tabs .tab").forEach(function (b) {
    b.addEventListener("click", function () {
      state.tab = b.getAttribute("data-tab");
      $$(".tabs .tab").forEach(function (x) { x.classList.toggle("active", x === b); });
      $$(".panel").forEach(function (p) {
        p.classList.toggle("active", p.id === "panel-" + state.tab);
      });
    });
  });

  $("#clubSearch").addEventListener("input", function (e) {
    state.clubQuery = e.target.value; renderClubs(state.data);
  });
  $("#nationalSearch").addEventListener("input", function (e) {
    state.natQuery = e.target.value; renderNational(state.data);
  });
  $("#beatSearch").addEventListener("input", function (e) {
    state.beatQuery = e.target.value; renderBeat(state.data);
  });
  $$("#nationalChips .chip").forEach(function (c) {
    c.addEventListener("click", function () {
      state.natFilter = c.getAttribute("data-filter");
      $$("#nationalChips .chip").forEach(function (x) {
        x.classList.toggle("active", x === c);
      });
      renderNational(state.data);
    });
  });
  $("#beatTeamChips").addEventListener("click", function (e) {
    var c = e.target.closest ? e.target.closest(".chip") : null;
    if (!c) return;
    state.beatTeam = c.getAttribute("data-team");
    renderBeat(state.data);
  });

  loadData();
})();
